#include "stdafx.h"#include "H_Class.h"#include "../ScriptoH/Trans.h"#include <SR_DCU.h>using namespace std;using namespace ns_translator;static SBlockCreate ENHAUXCALC( "ENHAUXCALC", SH_ENHAUXCALC::Create );#include <HPARM_INIT.h> #include "ParmVarInfo.h"LIST_PARM(SH_ENHAUXCALC,W_ENHAUXCALC,280)void SH_ENHAUXCALC::InitParm(){#include "Blocks/ENHAUXCALC.h"   s_defFlag = SVarInfo::efParam;#include "Blocks/ENHAUXCALC_P.h"  qsort ( VarInfo, kVarInfo, sizeof ( SVarInfo ), CompVarInfo );}void SH_ENHAUXCALC::OnReadProject( KBmBase *pRoot, KBmBase *pModule ){  ASS( _countof(W->EXPR)==_countof(m_Code) );  LPSTR pp[_countof(W->EXPR)];  for( int i=0; i<_countof(W->EXPR); ++i )  {    pp[i] = W->EXPR[i];  }  __super::CreateCodes( pRoot, pModule, m_Code, pp, _countof(W->EXPR) );}void SH_ENHAUXCALC::SaveBlock( HANDLE hFile ){  LPSTR pp[_countof(W->EXPR)];  for( int i=0; i<_countof(W->EXPR); ++i )  {    pp[i] = W->EXPR[i];  }  __super::SaveBlock( hFile, m_Code, pp, _countof(pp) );}bool SH_ENHAUXCALC::RestoreBlock( HANDLE hFile ){  LPSTR pp[_countof(W->EXPR)];  for( int i=0; i<_countof(W->EXPR); ++i )  {    pp[i] = W->EXPR[i];  }  return __super::RestoreBlock( hFile, m_Code, pp, _countof(pp) );}void SH_ENHAUXCALC::StepBeforeRestoreState( LPCSTR pSystemName, KBmBase *pRoot, KBmBase *pModule ){  bErrorInitialization = false;  for( int n=0; n<_countof(m_Code); ++n )  {    for( int i=0; i<m_Code[n].cVars; i++ )    {      KCalcVar &cv = ((KCalcVar*)m_Code[n].pVars)[i];      bool r = cv.Init( pRoot );      if( !r )      {        OutputDebugString( " (" );        OutputDebugString( BlockName );        OutputDebugString( ")\n" );        bErrorInitialization = true;#ifndef _DEBUG        break;#endif      }    }  }}void SH_ENHAUXCALC::StepT( SStepCalcParams &dt ){  InputConnectionsTransfer();  if( bErrorInitialization )  {    for( int n=0; n<_countof(m_Code); ++n )    {      W->EXECSTS[n] = W->_EXECSTS::Fail;      W->CSTS[n] = W->_CSTS::BAD;    }    W->PVSTS = W->_PVSTS::Bad;    return;  }  for( int n=0; n<_countof(m_Code); ++n )  {    if( Calc( m_Code[n], W->C[n] ) )    {      W->EXECSTS[n] = W->_EXECSTS::Ok;      W->CSTS[n] = W->_CSTS::NORMAL;      if( W->PENABLE[n] )        W->PP[n] = W->P[n] * W->CP[n];      else      {        W->P[n] = W->PSUB[n];        W->PP[n] = W->PSUB[n] * W->CP[n];      }    }    else    {      W->EXECSTS[n] = W->_EXECSTS::Fail;      W->CSTS[n] = W->_CSTS::BAD;    }  }  if( W->PVSRC.V >= W->_PVSRC::C1 && W->PVSRC.V <= W->_PVSRC::C8 )  {    int n = W->PVSRC.V - W->_PVSRC::C1 + 1;    W->PV = W->C[n];  }  else if( W->PVSRC.V >= W->_PVSRC::P1 && W->PVSRC.V <= W->_PVSRC::P6 )  {    int n = W->PVSRC.V - W->_PVSRC::P1 + 1;    W->PV = W->P[n];  }  else  {    ASSD(0);  }  if( W->PVSTSSRC.V >= W->_PVSTSSRC::C1 && W->PVSTSSRC.V <= W->_PVSTSSRC::C8 )  {    int n = W->PVSTSSRC.V - W->_PVSTSSRC::C1 + 1;    W->PVSTS.V = W->CSTS[n].V;  }  else if( W->PVSTSSRC.V >= W->_PVSTSSRC::PSTS1 && W->PVSTSSRC.V <= W->_PVSTSSRC::PSTS6 )  {    int n = W->PVSTSSRC.V - W->_PVSTSSRC::PSTS1 + 1;    W->PVSTS.V = W->PSTS[n].V;  }  else if( W->PVSTSSRC.V >= W->_PVSTSSRC::CSTS1 && W->PVSTSSRC.V <= W->_PVSTSSRC::CSTS8 )  {    int n = W->PVSTSSRC.V - W->_PVSTSSRC::CSTS1 + 1;    W->PVSTS.V = W->CSTS[n].V;  }  else  {    ASSD(0);  }  OutputConnectionsTransfer();}